/* 页面头部脚本：主题切换、时钟、背景刷新、返回顶部 */
function getNightCookie() {
  var m = document.cookie.match(/(?:^|;\s*)night=([^;]*)/);
  return m ? m[1] : '';
}

// 根据 cookie 应用主题（无 cookie 时按时间判断：22点~6点为夜间）
function applyTheme() {
  if (!document.body) return;
  var night = getNightCookie();
  if (night === '') {
    var hour = new Date().getHours();
    night = (hour > 22 || hour < 6) ? '1' : '0';
    document.cookie = 'night=' + night + ';path=/';
  }
  document.body.classList.toggle('night', night === '1');
}

// 切换到夜间模式
function dark() {
  document.body.classList.add('night');
  document.cookie = 'night=1;path=/';
}

// 切换到日间模式
function light() {
  document.body.classList.remove('night');
  document.cookie = 'night=0;path=/';
}

// 明暗主题切换入口（悬浮按钮调用）
function switchNightMode() {
  if (document.body.classList.contains('night')) {
    light();
  } else {
    dark();
  }
}

// 更新时间显示
function updateCurrentTime() {
  const e = new Date(),
    t = e.getHours().toString().padStart(2, '0'),
    n = e.getMinutes().toString().padStart(2, '0'),
    i = e.getSeconds().toString().padStart(2, '0'),
    o = `${t}:${n}:${i}`;
  const a = document.getElementById('current-time');
  if (a) a.textContent = o;
}

// 刷新随机背景图（由 CSS 提供首屏背景，这里只做定期换图）
function updateBackgroundImage() {
  document.body.style.backgroundImage = 'url(https://www.dmoe.cc/random.php)';
}

window.addEventListener('load', function () {
  applyTheme();
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);
  // 每30分钟换一次背景，避免频繁下载随机图片
  setInterval(updateBackgroundImage, 30 * 60 * 1000);
}, false);

// 滚动超过100px时显示返回顶部按钮
window.onscroll = function () {
  if (typeof $ === 'undefined') return; // jQuery 尚未加载时跳过
  document.documentElement.scrollTop + document.body.scrollTop > 100
    ? $('#topup').css({ display: 'block', transform: 'translateX(0px)', transition: '0.3s' })
    : $('#topup').css({ transform: 'translateX(60px)', transition: '0.3s' });
};

// 跟随系统深浅色变化时重新应用主题
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function () {
  applyTheme();
});
